for q in r['changes']:
 if q['id']=='r15':q.update(final=r'\inserted{\unsure{R|a}_{i,j}^{\deleted{\unsure{*}}}}',confidence='medium',evidence=dec['b02']['evidence'])
r['changes'].append({'id':'r42','place':'proof, after X_ell proper-subset X_i following implique','c':',','h':',','final':'No comma','evidence':'The final dotted i ends the line; there is no independent low mark after it before the next-line d-où. The blind reading omits the comma, confirmed directly from the whole proof crop.','confidence':'high','kind':'text not on the page','error_category':9,'diff_c':True,'diff_h':True,'marked_h':False,'crop':f'crops/second_{p}_b04.jpg','box':boxes['b04'],'consequential':''})
